// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address actor, address newOwner) public {
        // keep the domain wide: any actor, any proposed owner, including address(0)
        vm.assume(actor != address(0));

        vm.startPrank(actor);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // GENERAL RULE: if the ownership transfer completes, the contract's owner
        // is never the zero address (the reference reverts for newOwner == 0, so
        // this holds for every input; the mutant completes the call with
        // newOwner == address(0) and leaves owner() == address(0)).
        assertTrue(!ok || c.owner() != address(0));
    }
}

