pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // keep the domain WIDE: no exclusion of zero addresses for either param
        c.initialize(); // deployer (this test contract) becomes the owner

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Universal rule: whenever a transferOwnership call completes, the new
        // owner is a non-zero address and equals the requested newOwner.
        // The reference reverts for newOwner == address(0) (ok == false), so the
        // rule holds for every input; the mutant completes the call with
        // newOwner == address(0), setting owner() to zero and breaking it.
        assertTrue(!ok || (newOwner != address(0) && c.owner() == newOwner && c.owner() != address(0)));
    }
}

